import path from 'path';
import fs from 'fs';
import { execSync } from 'child_process';
import { log } from '../core/logger.js';
function detectPackageManager(cwd) {
    const pkgJsonPath = path.join(cwd, 'package.json');
    if (fs.existsSync(pkgJsonPath)) {
        try {
            const pkg = JSON.parse(fs.readFileSync(pkgJsonPath, 'utf-8'));
            if (typeof pkg.packageManager === 'string') {
                const match = pkg.packageManager.match(/^[^^]*?(npm|pnpm|yarn|bun)@/);
                if (match) {
                    const name = match[1];
                    return { name, addDevFlag: addDevCommand(name) };
                }
            }
        }
        catch { }
    }
    const lockFiles = [
        ['bun.lock', 'bun'],
        ['bun.lockb', 'bun'],
        ['pnpm-lock.yaml', 'pnpm'],
        ['yarn.lock', 'yarn'],
        ['package-lock.json', 'npm'],
        ['npm-shrinkwrap.json', 'npm'],
    ];
    for (const [file, name] of lockFiles) {
        if (fs.existsSync(path.join(cwd, file))) {
            return { name, addDevFlag: addDevCommand(name) };
        }
    }
    const userAgent = process.env['npm_config_user_agent'];
    if (userAgent) {
        for (const name of ['pnpm', 'yarn', 'bun', 'npm']) {
            if (userAgent.startsWith(name)) {
                return { name, addDevFlag: addDevCommand(name) };
            }
        }
    }
    return { name: 'npm', addDevFlag: addDevCommand('npm') };
}
function addDevCommand(pm) {
    switch (pm) {
        case 'pnpm': return 'pnpm add -D';
        case 'yarn': return 'yarn add -D';
        case 'bun': return 'bun add -d';
        case 'npm': return 'npm install --save-dev';
    }
}
export async function initCommand() {
    const cwd = process.cwd();
    const destination = path.resolve(cwd, 'webapkify.config.ts');
    if (fs.existsSync(destination)) {
        log.warn('webapkify.config.ts already exists ... aborting.');
        return;
    }
    const template = `/**
 * @file webapkify configuration file
 * @instructions Edit the properties below, then run: webapkify build [--release]
 * @details Hover over each property for more info.
 * @see https://npmjs.com/package/webapkify for full documentation
 */

import type { WebAPKifyConfig } from 'webapkify'

export default {
  appName: 'My App',
  appId: 'com.example.myapp',
  webDir: './dist',

  // icon: './icon.png',

  // clearTextDomains: ['localhost'],

  // permissions: {
  //   camera: true,
  //   fineLocation: true,
  //   postNotifications: true,
  // },

  // signing: {
  //   storeFile: './release.jks',
  //   storePassword: 'storePass',
  //   keyAlias: 'keyAlias',
  //   keyPassword: 'keyPass',
  // },
} satisfies WebAPKifyConfig`;
    fs.writeFileSync(destination, template);
    log.success('Created webapkify.config.ts');
    const { name: pm, addDevFlag } = detectPackageManager(cwd);
    log.dim(`Detected package manager: ${pm}`);
    log.dim(`Running: ${addDevFlag} webapkify`);
    try {
        execSync(`${addDevFlag} webapkify`, { cwd, stdio: 'inherit' });
        log.success('Added webapkify to devDependencies');
    }
    catch {
        log.warn(`Failed to auto-install webapkify. Run manually: ${addDevFlag} webapkify`);
    }
    log.dim('Edit webapkify.config.ts, then run: webapkify build');
}
